class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def supplyVaccine(root):
    def dfs(node):
        if not node:
            return 0, 0, float('inf')

        l_no_need, l_covered, l_kit = dfs(node.left)
        r_no_need, r_covered, r_kit = dfs(node.right)

        no_need = l_covered + r_covered
        covered = min(l_kit + r_covered, r_kit + l_covered, l_kit + r_kit)
        kit = min(no_need, l_kit + r_kit) + 1

        return no_need, covered, kit

    _, covered, kit = dfs(root)
    return min(covered, kit)

import sys
from collections import deque

def build_tree(nodes, f):
    if not nodes:
        return None
    root = TreeNode(int(next(f).strip()))
    q = deque([root])
    while q:
        current = q.popleft()
        left_val = next(f, None)
        right_val = next(f, None)
        if left_val and left_val.strip() != 'N':
            current.left = TreeNode(int(left_val.strip()))
            q.append(current.left)
        if right_val and right_val.strip() != 'N':
            current.right = TreeNode(int(right_val.strip()))
            q.append(current.right)
    return root

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    root = build_tree(data, iter(data))
    print(supplyVaccine(root))
